function [U,properties] = cazac_circulant(n,root,output)
%CAZAC_CIRCULANT Unitary circulant generated by a Zadoff-Chu sequence.
%   ROOT is an integer coprime to N (default 1). For odd N, the
%   unnormalized sequence c(k)=exp(-1i*pi*ROOT*k*(k+1)/N); for even N,
%   c(k)=exp(-1i*pi*ROOT*k^2/N), k=0:N-1.
%   U(j+1,k+1)=c(mod(j-k,N))/sqrt(N); every entry has modulus 1/sqrt(N).
%   The exact eigenvalues are fft(c)/sqrt(N), in Fourier frequency order.
%   Reference: D. C. Chu, IEEE Trans. Inf. Theory 18 (1972), 531-532.
%   Verified reference identifiers (see docs/MATRIX_ENCYCLOPEDIA.md):
%   [48] https://doi.org/10.1109/TIT.1972.1054840
properties={'square','unitary','normal','circulant','complex', ...
    'scalable','eigenvalues','parameter-dependent'};
if nargin==0,U=[];return;end
validateattributes(n,{'numeric'},{'scalar','integer','positive','finite'});
if nargin<2 || isempty(root),root=1;end
if nargin<3,output='matrix';end
if nargin==2 && (ischar(root)||isstring(root)),output=root;root=1;end
validateattributes(root,{'numeric'},{'scalar','integer','finite'});
if gcd(root,n)~=1
    error('cazac_circulant:Coprime','ROOT and N must be coprime.');
end
k=(0:n-1)';
c=exp(-1i*pi*root*(k.^2+mod(n,2)*k)/n);
if um_is_operator(output)
    lambda=fft(c)/sqrt(n);
    U=@(X,flag)um_fft_apply(X,flag,'circulant',lambda,[]);
    return
end
idx=mod((0:n-1)'-(0:n-1),n)+1;
U=c(idx)/sqrt(n);
end
